#!/usr/bin/env python3
"""
Round 112c (culprits), 29 September 2026. Needs round 111c.

Planted, bought or captured: the Slovak StB registers named in the note.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 112c (29 September)\n\nNeeds round 111c. Tiles patch round112c_tiles.py beside it (it carries 111c\'s\ncapture.py too).\n\n- First capture run (29 Sep): 2,796 cases (936 Wikidata, 1,799 lists, 61\n  compiled). Fixed in tiles from its log: Wikidata kinds found by name that are\n  not spying (militsiya, open-source intelligence, a skin mole, a sauce,\n  fictional ninjas, unnamed items) dropped and listed; query c (company people\n  convicted) split, it timed out; es.wikipedia parapolitics headings are\n  Firmantes (Ralito pact signers, ties) and Principales detenciones (alleged);\n  Mitrokhin "Accused but unconfirmed" -> alleged; SEC 403 -> "name email"\n  User-Agent with gzip; DOJ year pages taken from the index\'s links (1987 and\n  2014 on had other addresses); IPN failed every page on its certificate chain\n  -> certifi, then unchecked for its public pages, crawl restarted.\n- New tiles scripts/capture_stb.py: Slovak UPN StB registration books searched\n  for every Czech, Slovak and Czechoslovak office holder in Wikidata (born before\n  1975), kept only where the record\'s birth date equals Wikidata\'s; agent,\n  informer, resident, secret collaborator, confidant -> archive; candidates ->\n  alleged; watched people (NO, PO) and file kinds not drawn. Merged as part stb.\n- Probes now save the Czech ABS records search, protocols and help pages and a\n  sample UPN result page, for the Czech register next.\n- Script version app.js?v=1004.\n\n'
HEAD = "## Round 112c (29 September)"

def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round112c: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 111c" not in text:
        sys.exit("round112c: round 111c must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round112c: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round112c: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round112c: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 111c")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
